package com.ecole.gestion_scolaire.registration.service; import com.ecole.gestion_scolaire.registration.dto.*; import com.ecole.gestion_scolaire.registration.entity.RegistrationConsent; import com.ecole.gestion_scolaire.registration.repository.RegistrationConsentRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.OffsetDateTime; import java.util.*;
@Service @Transactional(readOnly=true) public class RegistrationConsentService {private final RegistrationConsentRepository repo;private final RegistrationCaseService cases;public RegistrationConsentService(RegistrationConsentRepository r,RegistrationCaseService c){repo=r;cases=c;}public List<RegistrationConsentResponse> list(Long id){cases.get(id);return repo.findByRegistrationCaseIdOrderByConsentTypeAsc(id).stream().map(this::map).toList();}@Transactional public RegistrationConsentResponse save(Long id,RegistrationConsentRequest r){String t=r.consentType().trim().toUpperCase(Locale.ROOT);var x=repo.findByRegistrationCaseIdAndConsentType(id,t).orElseGet(()->{var n=new RegistrationConsent();n.setRegistrationCase(cases.get(id));n.setConsentType(t);return n;});x.setAccepted(r.accepted());x.setAcceptedAt(r.accepted()?OffsetDateTime.now():null);x.setAcceptedByGuardianId(r.accepted()?r.acceptedByGuardianId():null);x.setNotes(r.notes());return map(repo.save(x));}private RegistrationConsentResponse map(RegistrationConsent x){return new RegistrationConsentResponse(x.getId(),x.getRegistrationCase().getId(),x.getConsentType(),x.isAccepted(),x.getAcceptedAt(),x.getAcceptedByGuardianId(),x.getNotes());}}
